package com.recgombak.batterymonitor;

import android.app.*;import android.content.*;import android.media.*;import android.os.*;import android.speech.tts.TextToSpeech;import java.util.Locale;

public class LowBatteryVoiceService extends Service{
 private static final String CHANNEL="rec_battery_voice";private BroadcastReceiver receiver;private TextToSpeech tts;private boolean ready=false;private PowerManager.WakeLock repeatWake;private final Handler h=new Handler(Looper.getMainLooper());private final Runnable repeatCheck=new Runnable(){public void run(){checkBattery();scheduleRepeat();}};

 @Override public void onCreate(){super.onCreate();createChannel();startForeground(4101,note("Memantau bateri tablet"));if(!"tablet".equals(Prefs.getRole(this))){stopSelf();return;}tts=new TextToSpeech(getApplicationContext(),s->{if(s==TextToSpeech.SUCCESS&&tts!=null){ready=true;try{tts.setLanguage(Locale.US);tts.setSpeechRate(.92f);tts.setAudioAttributes(new AudioAttributes.Builder().setUsage(AudioAttributes.USAGE_ALARM).setContentType(AudioAttributes.CONTENT_TYPE_SPEECH).build());}catch(Exception ignored){}checkBattery();}});receiver=new BroadcastReceiver(){public void onReceive(Context c,Intent i){checkBattery();scheduleRepeat();}};IntentFilter f=new IntentFilter(Intent.ACTION_BATTERY_CHANGED);f.addAction(Intent.ACTION_POWER_CONNECTED);f.addAction(Intent.ACTION_POWER_DISCONNECTED);try{registerReceiver(receiver,f);}catch(Exception ignored){}}
 private void checkBattery(){Intent i=registerReceiver(null,new IntentFilter(Intent.ACTION_BATTERY_CHANGED));if(i==null)return;int l=i.getIntExtra(BatteryManager.EXTRA_LEVEL,-1),s=i.getIntExtra(BatteryManager.EXTRA_SCALE,100),pct=s>0?Math.round(l*100f/s):l,st=i.getIntExtra(BatteryManager.EXTRA_STATUS,-1);boolean charging=st==BatteryManager.BATTERY_STATUS_CHARGING||st==BatteryManager.BATTERY_STATUS_FULL;int low=Prefs.sp(this).getInt("voice_low_threshold",65),full=Prefs.sp(this).getInt("voice_full_threshold",95),lowDrop=Prefs.sp(this).getInt("voice_low_repeat_drop",3);boolean lowRepeat=Prefs.sp(this).getBoolean("voice_low_repeat",false),fullRepeat=Prefs.sp(this).getBoolean("voice_full_repeat",false),fullEnabled=Prefs.sp(this).getBoolean("voice_full_enabled",true);long fullMs=Prefs.sp(this).getInt("voice_full_repeat_min",3)*60000L,now=System.currentTimeMillis(),lastFull=Prefs.sp(this).getLong("voice_last_full",0);int lastLowPct=Prefs.sp(this).getInt("voice_last_low_pct",-1);if(charging||pct>low){if(lastLowPct!=-1)Prefs.sp(this).edit().putInt("voice_last_low_pct",-1).apply();}else if(pct>=0&&pct<=low&&(lastLowPct==-1||(lowRepeat&&pct<=lastLowPct-Math.max(1,lowDrop)))){wakeScreen();speak(Prefs.getName(this)+", low battery. Please charge.");Prefs.sp(this).edit().putInt("voice_last_low_pct",pct).apply();notifyAlert(4102,Prefs.getName(this)+" • Low battery "+pct+"% — please charge");}if(!fullEnabled||!charging||pct<full){if(lastFull!=0)Prefs.sp(this).edit().putLong("voice_last_full",0).apply();}else if(pct>=full&&(lastFull==0||(fullRepeat&&now-lastFull>=fullMs))){wakeScreen();speak(Prefs.getName(this)+", battery full. Please unplug the charger.");Prefs.sp(this).edit().putLong("voice_last_full",now).apply();notifyAlert(4103,Prefs.getName(this)+" • Battery "+pct+"% — unplug charger");}}
 private void scheduleRepeat(){h.removeCallbacks(repeatCheck);Intent i=registerReceiver(null,new IntentFilter(Intent.ACTION_BATTERY_CHANGED));if(i==null){releaseRepeatWake();return;}int l=i.getIntExtra(BatteryManager.EXTRA_LEVEL,-1),s=i.getIntExtra(BatteryManager.EXTRA_SCALE,100),pct=s>0?Math.round(l*100f/s):l,st=i.getIntExtra(BatteryManager.EXTRA_STATUS,-1);boolean charging=st==BatteryManager.BATTERY_STATUS_CHARGING||st==BatteryManager.BATTERY_STATUS_FULL;int full=Prefs.sp(this).getInt("voice_full_threshold",95);boolean fr=Prefs.sp(this).getBoolean("voice_full_enabled",true)&&Prefs.sp(this).getBoolean("voice_full_repeat",false)&&charging&&pct>=full;if(!fr){releaseRepeatWake();return;}acquireRepeatWake();long delay=Prefs.sp(this).getInt("voice_full_repeat_min",3)*60000L;h.postDelayed(repeatCheck,Math.max(60000L,delay));}
 private void acquireRepeatWake(){try{if(repeatWake==null){PowerManager pm=(PowerManager)getSystemService(POWER_SERVICE);repeatWake=pm.newWakeLock(PowerManager.PARTIAL_WAKE_LOCK,"REC:ActiveBatteryRepeat");repeatWake.setReferenceCounted(false);}if(!repeatWake.isHeld())repeatWake.acquire();}catch(Exception ignored){}}
 private void releaseRepeatWake(){try{if(repeatWake!=null&&repeatWake.isHeld())repeatWake.release();}catch(Exception ignored){}}
 private void wakeScreen(){try{PowerManager pm=(PowerManager)getSystemService(POWER_SERVICE);PowerManager.WakeLock w=pm.newWakeLock(PowerManager.SCREEN_BRIGHT_WAKE_LOCK|PowerManager.ACQUIRE_CAUSES_WAKEUP,"REC:BatteryAlertScreen");w.acquire(12000);}catch(Exception ignored){}}
 private void speak(String x){if(!ready||tts==null)return;try{AudioManager a=(AudioManager)getSystemService(AUDIO_SERVICE);a.setStreamVolume(AudioManager.STREAM_ALARM,a.getStreamMaxVolume(AudioManager.STREAM_ALARM),0);tts.speak(x,TextToSpeech.QUEUE_FLUSH,null,"battery_voice");}catch(Exception ignored){}}
 private void notifyAlert(int id,String x){try{((NotificationManager)getSystemService(NOTIFICATION_SERVICE)).notify(id,note(x));}catch(Exception ignored){}}
 private void createChannel(){if(Build.VERSION.SDK_INT>=26)getSystemService(NotificationManager.class).createNotificationChannel(new NotificationChannel(CHANNEL,"Tablet Battery Voice",NotificationManager.IMPORTANCE_HIGH));}
 private Notification note(String x){Notification.Builder b=Build.VERSION.SDK_INT>=26?new Notification.Builder(this,CHANNEL):new Notification.Builder(this);return b.setContentTitle("REC Battery Monitor").setContentText(x).setStyle(new Notification.BigTextStyle().bigText(x)).setSmallIcon(android.R.drawable.ic_lock_idle_low_battery).setOngoing(true).build();}
 @Override public int onStartCommand(Intent i,int f,int id){checkBattery();scheduleRepeat();return START_STICKY;}@Override public void onDestroy(){h.removeCallbacks(repeatCheck);releaseRepeatWake();try{if(receiver!=null)unregisterReceiver(receiver);}catch(Exception ignored){}try{if(tts!=null){tts.stop();tts.shutdown();}}catch(Exception ignored){}super.onDestroy();}@Override public IBinder onBind(Intent i){return null;}
}
